visualVariables.valueExpression:
  $feature["P0020002"];
$feature["P0020003"];


  var fieldNames = [ "P0020002", "P0020003" ];
  var numFields = 2;
  var maxValueField = null;
  var maxValue = -Infinity;
  var value, i, totalValue = null;

  for(i = 0; i < numFields; i++) {
    value = $feature[fieldNames[i]];

    if(value > 0) {
      if(value > maxValue) {
        maxValue = value;
        maxValueField = fieldNames[i];
      }
      else if (value == maxValue) {
        maxValueField = null;
      }
    }

  if(value != null && value >= 0) {
    if (totalValue == null) { totalValue = 0; }
    totalValue = totalValue + value;
  }

  }


  var strength = null;

  if (maxValueField != null && totalValue > 0) {
    strength = (maxValue / totalValue) * 100;
  }

  return strength;

